SET NAMES utf8mb4;
CREATE TABLE mall_category(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(32) NOT NULL UNIQUE,icon_url VARCHAR(512) NOT NULL DEFAULT '',sort_no INT NOT NULL DEFAULT 0,status CHAR(1) NOT NULL DEFAULT '0',create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mall_content_category(id BIGINT AUTO_INCREMENT PRIMARY KEY,category_code VARCHAR(32) NOT NULL UNIQUE,category_name VARCHAR(64) NOT NULL,status CHAR(1) NOT NULL DEFAULT '0',sort_no INT NOT NULL DEFAULT 0,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mall_content_article(id BIGINT AUTO_INCREMENT PRIMARY KEY,category_id BIGINT NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(128) NOT NULL,summary VARCHAR(500) NOT NULL DEFAULT '',cover_image_key VARCHAR(512) NOT NULL DEFAULT '',body_html MEDIUMTEXT NOT NULL,status CHAR(1) NOT NULL DEFAULT '1',published_at DATETIME NULL,sort_no INT NOT NULL DEFAULT 0,favorite_count INT NOT NULL DEFAULT 0,view_count INT NOT NULL DEFAULT 0,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mall_invite_gift_rule(id BIGINT AUTO_INCREMENT PRIMARY KEY,rule_name VARCHAR(80) NOT NULL,required_completed_invites INT NOT NULL DEFAULT 3,reward_points INT NOT NULL DEFAULT 188,gift_value DECIMAL(10,2) NOT NULL DEFAULT 0,gift_contents VARCHAR(500) NOT NULL DEFAULT '',status CHAR(1) NOT NULL DEFAULT '0',start_time DATETIME NULL,end_time DATETIME NULL,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mall_invite_gift_claim(id BIGINT AUTO_INCREMENT PRIMARY KEY,claim_no VARCHAR(40) NOT NULL UNIQUE,request_no VARCHAR(80) NOT NULL UNIQUE,rule_id BIGINT NOT NULL,customer_id BIGINT NOT NULL,completed_invite_count INT NOT NULL,reward_points INT NOT NULL,reward_snapshot VARCHAR(500) NOT NULL DEFAULT '',status VARCHAR(24) NOT NULL,claim_time DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_invite_gift_customer_rule(customer_id,rule_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mall_page_module(id BIGINT AUTO_INCREMENT PRIMARY KEY,module_key VARCHAR(100) NOT NULL UNIQUE,page_code VARCHAR(64) NOT NULL,module_code VARCHAR(64) NOT NULL,english_title VARCHAR(120) NOT NULL DEFAULT '',title VARCHAR(160) NOT NULL DEFAULT '',subtitle VARCHAR(255) NOT NULL DEFAULT '',description VARCHAR(1000) NOT NULL DEFAULT '',image_asset_id BIGINT NULL,image_url VARCHAR(500) NOT NULL DEFAULT '',jump_type VARCHAR(32) NOT NULL DEFAULT 'none',jump_target VARCHAR(255) NOT NULL DEFAULT '',config_json JSON NOT NULL,status CHAR(1) NOT NULL DEFAULT '0',sort_no INT NOT NULL DEFAULT 0,publish_time DATETIME NULL,version_no INT NOT NULL DEFAULT 1,created_by BIGINT NULL,updated_by BIGINT NULL,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO mall_category(name,sort_no,status) VALUES('红茶',10,'0'),('绿茶',20,'0'),('白茶',30,'0');
